162: /** Part types that AgentMessage actually renders as visible content
163:  * (drives the "interrupted" vs "aborted" copy below). Excludes invisible
164:  * parts like step-start. MUST stay in sync with the render switch in the
165:  * component body: a renderable part added there but not here makes an aborted
166:  * message with visible output wrongly read "Query aborted". */
167: function isRenderedPart(part: TypedUIMessage["parts"][number]): boolean {
168:   if (part.type === "text") return part.text.trim().length > 0;
169:   if (part.type === "reasoning") return true;
170:   if (isToolUIPart(part)) return true;
171:   return (
172:     part.type === "data-task" ||
173:     part.type === "data-task-created" ||
174:     part.type === "data-task-updated" ||
175:     part.type === "data-document"
176:   );
177: }
